export const AT_MOST_PREFIX = 'at-most-';
export const NOT_FAILED_TERM = 'last-run-not-failed';
export const NOT_PARKED_TERM = 'last-run-not-parked';

// The term a cadence is stated as, and the cadence read back out of one. An argument
// outside the vocabulary reads back as null, which is what the author-time check reports.
export const scheduleTermFor = (cadence) => `${SCHEDULE_TERM}:${AT_MOST_PREFIX}${cadence}`;

input.command:
cd /home/user && cat > /tmp/claude-0/-home-user-Shepherd/e8fcfbb7-19ed-55e8-a143-2a5d1181619f/scratchpad/accept.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
const [,, file, reason] = process.argv;
const text = readFileSync(file, 'utf8');
const d = JSON.parse(text);
const entry = { rule: 'scheduler-workflow-shape', path: '.github/workflows/claudinite-scheduler.yml', reason };
d.accept = [...(d.accept ?? []), entry];
writeFileSync(file, JSON.stringify(d, null, 2) + (text.endsWith('\n') ? '\n' : ''));
EOF
S=/tmp/claude-0/-home-user-Shepherd/e8fcfbb7-19ed-55e8-a143-2a5d1181619f/scratchpad/accept.mjs
DORM="the project is dormant, so its scheduler stops before doing any work; the schedule trigger is removed so Actions stops starting runs that do nothing. Restore the cron when the project wakes."
for r in hitbut wip shoutsandwhispers laughcounter; do node $S $r/.claudinite-settings.json "$DORM"; done
node $S tldr/.claudinite-settings.json "the owner turned this repo's scheduled runs off; the scheduler still runs on workflow_dispatch. Restore the cron to resume scheduled upkeep."
ONCE="the owner cut this repo to one tick a day to halve its scheduled runs; daily-period tasks still run, and drain-tick work waits for the next day's tick."
node $S missingbulbwebsite/.claudinite-settings.json "$ONCE"; node $S googlecalendareventcreator/.claudinite-settings.json "$ONCE"
for r in hitbut wip shoutsandwhispers laughcounter tldr missingbulbwebsite googlecalendareventcreator; do echo "== $r"; git -C $r diff --stat | tail -1; (cd $r && node .claudinite/shared/engine/checks/check_the_world.mjs 2>&1 | grep -E "^\[BLOCKING\]|blocking,"; echo "EXIT:${PIPESTATUS[0]}"); done

